(()=>{'use strict';const menuToggle=document.querySelector('.menu-toggle');const primaryNav=document.querySelector('.primary-nav');const dropdown=document.querySelector('.nav-dropdown');const dropdownTrigger=document.querySelector('.dropdown-trigger');const yearElement=document.querySelector('#current-year');if(yearElement)yearElement.textContent=String(new Date().getFullYear());const currentFile=(window.location.pathname.split('/').pop()||'index.html').toLowerCase();const activeNav=currentFile==='index.html'||currentFile===''?'home':currentFile==='kurumsal.html'?'kurumsal':currentFile==='markalar.html'?'brands':currentFile==='teklif-al.html'?'quote':currentFile==='iletisim.html'?'contact':(currentFile==='urun-gruplari.html'||/^(toner-kartus|kartus-murekkep|yazici-fotokopi|kagit-etiket|bilgisayar-cevre-birimleri|bilgisayar-bilesenleri|tablet-mobil-cihazlar|ergonomik-calisma-urunleri|ag-iletisim-urunleri|kablo-baglanti-urunleri|telefon-santral-urunleri|ups-guc-cozumleri|yazilim-lisans|depolama-bellek|sunucu-veri-merkezi|tarayici-arsiv-urunleri|ofis-makineleri|sunum-toplanti-urunleri|dijital-tabela-ekran|kurumsal-toplu-tedarik|guvenlik-sistemleri|gecis-kontrol-alarm|barkod-pos-urunleri|yazarkasa-perakende-urunleri)\.html$/.test(currentFile))?'products':'';document.querySelectorAll('[data-nav]').forEach((link)=>{const isCurrent=link.dataset.nav===activeNav;link.classList.toggle('active',isCurrent);if(isCurrent)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});function closeMobileMenu(){if(!menuToggle||!primaryNav)return;menuToggle.setAttribute('aria-expanded','false');menuToggle.setAttribute('aria-label','Menüyü aç');primaryNav.classList.remove('open');}
menuToggle?.addEventListener('click',()=>{const isOpen=menuToggle.getAttribute('aria-expanded')==='true';menuToggle.setAttribute('aria-expanded',String(!isOpen));menuToggle.setAttribute('aria-label',isOpen?'Menüyü aç':'Menüyü kapat');primaryNav?.classList.toggle('open',!isOpen);});dropdownTrigger?.addEventListener('click',(event)=>{event.stopPropagation();const isOpen=dropdownTrigger.getAttribute('aria-expanded')==='true';dropdownTrigger.setAttribute('aria-expanded',String(!isOpen));dropdown?.classList.toggle('open',!isOpen);if(isOpen)dropdownTrigger.blur();});document.addEventListener('click',(event)=>{if(dropdown&&!dropdown.contains(event.target)){dropdown.classList.remove('open');dropdownTrigger?.setAttribute('aria-expanded','false');}
if(primaryNav?.classList.contains('open')&&!primaryNav.contains(event.target)&&!menuToggle?.contains(event.target))closeMobileMenu();});document.addEventListener('keydown',(event)=>{if(event.key==='Escape'){if(dropdown?.contains(document.activeElement))document.activeElement.blur();closeMobileMenu();dropdown?.classList.remove('open');dropdownTrigger?.setAttribute('aria-expanded','false');}});primaryNav?.querySelectorAll('a').forEach((link)=>link.addEventListener('click',()=>{closeMobileMenu();dropdown?.classList.remove('open');dropdownTrigger?.setAttribute('aria-expanded','false');}));})();